import { createHash, randomUUID } from 'node:crypto';
import type { Result } from '@polyphony/core-types';
import type { OperationOptions, StoragePort } from '@polyphony/state/contracts';
import type { SqlScope } from '@polyphony/state/adapters/sqlite';
import {
  toJobId,
  type JobParameters,
  type JobRepository,
  type JobsQueryOptions,
  type JobsResult,
  type JobsOverview,
  type JobId,
} from 'agenda';
import { z } from 'zod';

// Bounded compatibility fixture, NOT a production queue or general Agenda driver.
// All records are generated by these probe consumers; no domain data is used.
const Input = z.object({
  id: z.string(),
  value: z.number(),
  maxAttempts: z.number().int().positive(),
});
const Row = z.object({
  id: z.string(),
  name: z.string(),
  hash: z.string(),
  value: z.number(),
  maxAttempts: z.number().int().positive(),
  attempts: z.number().int().nonnegative(),
  state: z.enum(['queued', 'running', 'completed', 'failed', 'cancelled']),
  notBefore: z.number(),
  nextRunAt: z.number().nullable(),
  lease: z.string().nullable(),
  startedLease: z.string().nullable(),
  lockedAt: z.number().nullable(),
  lastRunAt: z.number().nullable(),
  lastFinishedAt: z.number().nullable(),
  result: z.number().nullable(),
});
export type ProbeRow = z.infer<typeof Row>;
const Identity = z.tuple([z.string(), z.string().nullable()]);
export const migrations = [
  {
    id: 'queue_probe_1',
    sql: 'CREATE TABLE probe_jobs(id TEXT PRIMARY KEY, body TEXT NOT NULL);',
  },
];
export const limits = (): OperationOptions => ({
  signal: new AbortController().signal,
  timeoutMs: 5_000,
});
export function required<T, E>(value: Result<T, E>): T {
  if (!value.ok)
    throw new Error(`Storage operation failed: ${JSON.stringify(value.error)}`);
  return value.value;
}

export class Repository implements JobRepository {
  readonly storage: StoragePort<SqlScope>;
  // Test barriers intercept the real public repository boundary, not Agenda internals.
  onReserved?: (job: JobParameters) => Promise<void>;
  onStarted?: (job: JobParameters) => Promise<void>;
  onFinalized?: (job: JobParameters) => Promise<void>;
  onScan?: () => Promise<void>;
  accepting = true;
  constructor(storage: StoragePort<SqlScope>) {
    this.storage = storage;
  }

  async connect(): Promise<void> {
    required(await this.storage.checkSchema(limits()));
  }
  async read(id: string): Promise<ProbeRow | undefined> {
    return required(
      await this.storage.readSnapshot(
        async (sql) => this.load(sql, id),
        limits(),
      ),
    );
  }
  private async load(sql: SqlScope, id: string): Promise<ProbeRow | undefined> {
    const rows = await sql.all('SELECT body FROM probe_jobs WHERE id = ?', [
      id,
    ]);
    return rows.length ? Row.parse(JSON.parse(String(rows[0][0]))) : undefined;
  }
  private async put(sql: SqlScope, row: ProbeRow): Promise<void> {
    await sql.run(
      'INSERT INTO probe_jobs(id,body) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET body=excluded.body',
      [row.id, JSON.stringify(Row.parse(row))],
    );
  }
  private async write<T>(action: (sql: SqlScope) => Promise<T>): Promise<T> {
    return required(
      await this.storage.transact(
        async (sql) => ({ ok: true, value: await action(sql) }),
        limits(),
      ),
    );
  }
  private identity(id: string | undefined): [string, string | null] {
    return Identity.parse(JSON.parse(id ?? 'null'));
  }
  private parameters(row: ProbeRow): JobParameters {
    return {
      // Agenda JobId is an opaque delivery identity. Public queue ID stays row.id.
      // Encoding the reservation here also fences unlockJobs(ids) without private API.
      _id: toJobId(JSON.stringify([row.id, row.lease])),
      name: row.name,
      type: 'normal',
      priority: 0,
      data: { id: row.id, value: row.value, maxAttempts: row.maxAttempts },
      nextRunAt: row.nextRunAt === null ? null : new Date(row.nextRunAt),
      lockedAt: row.lockedAt === null ? undefined : new Date(row.lockedAt),
      lastRunAt: row.lastRunAt === null ? undefined : new Date(row.lastRunAt),
      lastFinishedAt:
        row.lastFinishedAt === null ? undefined : new Date(row.lastFinishedAt),
      disabled: row.state === 'cancelled',
    };
  }
  async saveJob<DATA>(job: JobParameters<DATA>): Promise<JobParameters<DATA>> {
    const input = Input.parse(job.data);
    const hash = createHash('sha256')
      .update(JSON.stringify([job.name, input]))
      .digest('hex');
    const row = await this.write(async (sql) => {
      const existing = await this.load(sql, input.id);
      if (existing) {
        if (existing.hash !== hash) throw new Error('ID/hash conflict');
        return existing;
      }
      const created: ProbeRow = {
        ...input,
        name: job.name,
        hash,
        attempts: 0,
        state: 'queued',
        notBefore: job.nextRunAt?.getTime() ?? 0,
        nextRunAt: job.nextRunAt?.getTime() ?? 0,
        lease: null,
        startedLease: null,
        lockedAt: null,
        lastRunAt: null,
        lastFinishedAt: null,
        result: null,
      };
      await this.put(sql, created);
      return created;
    });
    return { ...job, _id: this.parameters(row)._id };
  }
  async getJobById(identity: string): Promise<JobParameters | null> {
    const [id, lease] = this.identity(identity);
    const row = await this.read(id);
    return row && row.lease === lease ? this.parameters(row) : null;
  }
  async queryJobs(options?: JobsQueryOptions): Promise<JobsResult> {
    if (!options?.id)
      throw new Error('Probe only supports processor identity queries');
    const job = await this.getJobById(options.id);
    return {
      jobs: job ? [{ ...job, _id: toJobId(options.id), state: 'running' }] : [],
      total: job ? 1 : 0,
    };
  }
  async getNextJobToRun(
    name: string,
    nextScanAt: Date,
    lockDeadline: Date,
    now = new Date(),
  ): Promise<JobParameters | undefined> {
    if (!this.accepting) return;
    const selected = await this.write(async (sql) => {
      const rows = await sql.all('SELECT body FROM probe_jobs ORDER BY id');
      for (const values of rows) {
        const row = Row.parse(JSON.parse(String(values[0])));
        if (
          !this.accepting ||
          row.name !== name ||
          !['queued', 'running'].includes(row.state)
        )
          continue;
        if (row.lockedAt !== null && row.lockedAt > lockDeadline.getTime())
          continue;
        if (row.attempts >= row.maxAttempts) {
          await this.put(sql, {
            ...row,
            state: 'failed',
            lease: null,
            lockedAt: null,
            nextRunAt: null,
          });
          continue;
        }
        if (row.notBefore > nextScanAt.getTime()) continue;
        const reserved = {
          ...row,
          state: 'queued' as const,
          lease: randomUUID(),
          lockedAt: now.getTime(),
          nextRunAt: row.notBefore,
        };
        await this.put(sql, reserved);
        return this.parameters(reserved);
      }
    });
    await this.onScan?.();
    if (selected) await this.onReserved?.(selected);
    return selected;
  }
  async lockJob(job: JobParameters): Promise<JobParameters | undefined> {
    // Immediate delivery is not used: the probe exclusively exercises Agenda polling.
    throw new Error(`Unexpected immediate lock: ${job.name}`);
  }
  async saveJobState(job: JobParameters): Promise<void> {
    const [id, lease] = this.identity(job._id);
    let began = false;
    try {
      await this.write(async (sql) => {
        const row = await this.load(sql, id);
        if (!row || !lease || row.lease !== lease)
          throw new Error('stale attempt');
        if (['completed', 'failed', 'cancelled'].includes(row.state)) return;
        if (job.lockedAt && job.lastRunAt && row.startedLease !== lease) {
          if (!this.accepting || row.attempts >= row.maxAttempts)
            throw new Error('dispatch denied');
          began = true;
          await this.put(sql, {
            ...row,
            state: 'running',
            attempts: row.attempts + 1,
            startedLease: lease,
            lastRunAt: job.lastRunAt.getTime(),
          });
        } else if (job.lockedAt) {
          await this.put(sql, { ...row, lockedAt: job.lockedAt.getTime() });
        } else {
          const failed = row.attempts >= row.maxAttempts;
          const next = job.nextRunAt?.getTime() ?? Date.now();
          await this.put(sql, {
            ...row,
            state: failed ? 'failed' : 'queued',
            lease: null,
            lockedAt: null,
            notBefore: next,
            nextRunAt: failed ? null : next,
          });
        }
      });
    } catch (error) {
      // A failed acknowledgement does not prove rollback. Only the durable record
      // for this exact reservation can authorize entering the handler once.
      if (!began) throw error;
      const durable = await this.read(id);
      if (
        durable?.state !== 'running' ||
        durable.startedLease !== lease ||
        durable.lease !== lease
      )
        throw error;
    }
    if (began) await this.onStarted?.(job);
    if (!job.lockedAt) await this.onFinalized?.(job);
  }
  async complete(job: JobParameters, result: number): Promise<void> {
    const [id, lease] = this.identity(job._id);
    await this.write(async (sql) => {
      const row = await this.load(sql, id);
      if (!row || row.lease !== lease || row.state !== 'running')
        throw new Error('stale completion');
      await this.put(sql, {
        ...row,
        state: 'completed',
        result,
        nextRunAt: null,
        lastFinishedAt: Date.now(),
      });
    });
  }
  async unlockJob(job: JobParameters): Promise<void> {
    if (job._id) await this.unlockJobs([job._id]);
  }
  async unlockJobs(ids: (JobId | string)[]): Promise<void> {
    await this.write(async (sql) => {
      for (const identity of ids) {
        const [id, lease] = this.identity(identity);
        const row = await this.load(sql, id);
        if (row && lease && row.lease === lease && row.state === 'queued')
          await this.put(sql, { ...row, lease: null, lockedAt: null });
      }
    });
  }
  // Deliberately fail-closed: admin/search/cron are NOT claimed by this experiment.
  async getJobsOverview(): Promise<JobsOverview[]> {
    throw new Error('Not in probe');
  }
  async getDistinctJobNames(): Promise<string[]> {
    throw new Error('Not in probe');
  }
  async getQueueSize(): Promise<number> {
    throw new Error('Not in probe');
  }
  async removeJobs(): Promise<number> {
    throw new Error('Owner receipt required');
  }
  async disableJobs(): Promise<number> {
    throw new Error('Not in probe');
  }
  async enableJobs(): Promise<number> {
    throw new Error('Not in probe');
  }
  async purgeAllJobs(): Promise<number> {
    throw new Error('Owner receipt required');
  }
}
